// Let's look for any block in front of us (negative X direction) and navigate to it or step towards it.
let pos = bot.entity.position;
let blocks = bot.findBlocks({
    matching: block => block && block.name !== 'air',
    maxDistance: 10,
    count: 20
});

// Sort blocks by distance in negative X direction
let forwardBlocks = blocks.filter(b => b.x < pos.x).sort((a, b) => a.x - b.x);

if (forwardBlocks.length > 0) {
    let target = forwardBlocks[0];
    let block = bot.blockAt(target);
    console.log("Moving towards forward block:", block.name, target);
    await skills.goToNearestBlock(bot, block.name, 15, 1);
} else {
    // Just move forward and jump if no specific block found
    bot.setControlState('forward', true);
    bot.setControlState('jump', true);
    await skills.wait(bot, 1500);
    bot.setControlState('forward', false);
    bot.setControlState('jump', false);
}```
